[data-workspace-area="conversation"] .messages-timeline-scroll,[data-chat-header]{background:transparent!important}
[data-chat-header]{backdrop-filter:blur(6px)}
[data-user-message-bubble]{background:rgba(10,19,48,.8)!important;border:1px solid rgba(255,138,92,.35)!important;backdrop-filter:blur(4px)}
.chat-markdown{text-shadow:0 1px 2px rgba(0,0,0,.95),0 0 6px rgba(0,0,0,.6)}
.chat-markdown-codeblock{background:rgba(10,19,48,.88)!important}
[data-slot="composer-host"]{background:rgba(10,19,48,.82)!important;backdrop-filter:blur(8px);border-color:rgba(255,138,92,.4)!important}
